    conceptoA: { escuela: "s4", nombre: "Realidad como construcción del sistema observador (cibernética de segundo orden)" },
    conceptoB: { escuela: "p1", nombre: "Verdad histórica reprimida a develar" },
    relacion: "inconmensurable",
