    nota:
      "Esta es, en la literatura de epistemología de la terapia familiar, una de las incompatibilidades más citadas explícitamente como tal: el propio giro hacia la cibernética de segundo orden (Milán tardío, von Foerster) se formuló como ruptura declarada contra los modelos «de primer orden» —entre los que se cuenta explícitamente el psicoanálisis clásico— que presuponen un observador-terapeuta situado fuera del sistema, capaz de acceder a una realidad objetiva (la verdad histórica reprimida del paciente) independiente de su propia observación. Para la cibernética de segundo orden, no existe tal punto de observación externo: el terapeuta es siempre parte del sistema que pretende describir, y toda «realidad» clínica es una construcción coemergente de la interacción observador-observado, sin un hecho históricamente verdadero a develar detrás del síntoma. No es que ambas escuelas ofrezcan explicaciones distintas del mismo fenómeno: divergen en si existe siquiera un hecho objetivo independiente del observador que pueda ser el objeto de la explicación. Inconmensurabilidad declarada por la propia escuela sistémica de segundo orden, no una lectura forzada desde fuera.",
