    fidelidad: "baja",
    nota:
      "Ambos conceptos apelan a un modo de contacto con la experiencia inmediata distinto del pensamiento discursivo ordinario, lo que puede sugerir un parentesco cercano. Pero se trata de procesos distintos: la sensación sentida de Gendlin es una percepción corporal difusa y cambiante sobre una situación vital concreta —tiene contenido específico, situacional, que se «pregunta» al cuerpo en cada sesión—; el yo-como-contexto de ACT no es una sensación corporal con contenido específico sino una perspectiva verbal estable y deíctica («aquí-ahora-yo») desde la cual se observan pensamientos, emociones y sensaciones —incluida la propia sensación sentida, si apareciera—, sin contenido propio. Falso amigo: uno es un contenido experiencial corporal cambiante que se explora, el otro es la perspectiva estable —sin contenido— desde la que se observa cualquier contenido, incluidas las sensaciones corporales.",
