    nota:
      "Ambas escuelas comparten la premisa del giro lingüístico: el lenguaje no describe pasivamente una realidad psíquica ya dada, sino que la organiza y en cierto sentido la constituye («el inconsciente está estructurado como un lenguaje», Lacan). Pero el alcance de esa premisa es distinto: para Lacan, lo Simbólico es un orden estructural transindividual (la Ley, el Nombre-del-Padre, el significante) que preexiste al sujeto y lo determina desde antes de su nacimiento, dentro de una relectura estructuralista del psicoanálisis freudiano; para la terapia narrativa, el lenguaje constituye historias personales y culturales relativamente locales y modificables en la conversación terapéutica presente, sin el aparato estructuralista de registros fijos (Real, Simbólico, Imaginario) que organiza toda la clínica lacaniana. Solapamiento parcial: ambas afirman que el lenguaje constituye la experiencia, pero con arquitecturas teóricas —estructuralismo psicoanalítico vs. construccionismo social— que no son intercambiables.",
