    nota:
      "Kernberg construye explícitamente su concepto de escisión sobre la posición esquizoparanoide kleiniana, por lo que la fidelidad aquí es alta y la relación está declarada en el propio corpus teórico, no inferida desde fuera. La diferencia es de alcance temporal y clínico: en Klein, la posición esquizoparanoide es una fase normativa universal del desarrollo temprano (los primeros meses de vida), que todo bebé atraviesa y que normalmente se resuelve al pasar a la posición depresiva; en Kernberg, la escisión persistente en la vida adulta —cuando la posición esquizoparanoide no se resuelve evolutivamente— es específicamente patológica y organiza la Organización Límite de la Personalidad. Solapamiento de fidelidad alta: es, en rigor, el mismo mecanismo mental descrito en dos momentos —uno normativo-evolutivo, el otro patológico-persistente— de la misma línea teórica kleiniana-kernbergiana.",
