    nota:
      "No se trata de dos escuelas que describan el mismo fenómeno con distinto vocabulario, sino de una crítica declarada de una escuela hacia un concepto de la otra. Jung postula el ánima (la imagen arquetípica de lo femenino en el hombre) y el ánimus (la imagen arquetípica de lo masculino en la mujer) como estructuras universales del inconsciente colectivo, cuya integración es parte de la individuación; la terapia feminista, con su criterio político explícito, ha señalado que estos arquetipos reproducen y naturalizan roles de género culturalmente específicos como si fueran universales psíquicos, reforzando —en vez de cuestionar— el propio esencialismo de género que buena parte de la clínica feminista busca desmontar. Falso amigo en sentido fuerte: no hay aquí un puente traducible, sino una impugnación directa del estatus universal que Jung atribuye al concepto.",
