      "Ambas técnicas, de la misma tradición estructural-experiencial de mediados de siglo XX, sacan el patrón relacional de la conversación verbal y lo hacen visible y corporal en el espacio de la sesión, en vez de limitarse a describirlo con palabras. La diferencia es de propósito inmediato: la escultura familiar de Satir es una representación estática y simbólica —los miembros se colocan físicamente para mostrar posturas, distancias y jerarquías del sistema— con fines primariamente de insight y catarsis compartida; el enactment de Minuchin es una interacción dinámica y en vivo —se pide a la familia interactuar activamente sobre un conflicto real— con fines primariamente de intervención y reestructuración inmediata de límites y jerarquías. Solapamiento de fidelidad alta: ambas materializan el patrón relacional en el cuerpo y el espacio de la sesión, difiriendo sobre todo en si el objetivo inmediato es mostrar (escultura) o reestructurar en vivo (enactment).",
