    nota:
      "Ambos conceptos sostienen que actuar de acuerdo con lo que verdaderamente importa —no solo aliviar el malestar inmediato— es el criterio último de una vida bien vivida. Pero el terreno en que se juega ese «actuar según lo que importa» es distinto: los valores en ACT son cualidades de acción elegidas libremente por el individuo, evaluadas dentro de su propia vida y sin referencia obligatoria a otras personas concretas; la ética relacional de Boszormenyi-Nagy exige explícitamente un balance de dar y recibir entre personas reales dentro de un sistema familiar multigeneracional, y no se satisface con una elección individual de valores si esa elección no repara el desequilibrio relacional concreto. Análogo funcional de fidelidad baja: ambos valoran la acción comprometida por encima del alivio sintomático, pero uno la ancla en la elección individual y el otro en el equilibrio ético entre personas reales.",
