    nota:
      "Ambos conceptos sostienen que ciertas necesidades básicas deben ser suplidas externamente antes de que la persona pueda funcionar de forma autónoma y saludable, y que su carencia prolongada produce patología duradera. Pero el estatus y el contenido de esas necesidades difieren: las necesidades de déficit de Maslow (fisiológicas, de seguridad, de pertenencia, de estima) son universales, jerárquicas y no específicas de la relación terapéutica; las funciones de selfobjeto de Kohut son necesidades específicamente relacionales de espejo, idealización y gemelaridad, cuya provisión inadecuada en la infancia se repara específicamente dentro del vínculo terapéutico mediante empatía sostenida, no mediante la satisfacción genérica de necesidades básicas de cualquier tipo. Análogo funcional de fidelidad baja: ambos legitiman la dependencia de un suplemento externo como parte normal del desarrollo, pero con contenidos y escenarios de reparación distintos.",
