      "Ambas técnicas, de la misma tradición sistémica de mediados de siglo XX, intervienen deliberadamente sobre el equilibrio del sistema familiar en vez de dirigirse directamente al individuo síntoma. Pero el mecanismo de esa intervención difiere: el desequilibramiento de Minuchin es una alianza temporal y deliberada del terapeuta con un subsistema (p. ej. apoyando al miembro subordinado) para alterar en vivo la jerarquía disfuncional; la connotación positiva de Milán no forma ninguna alianza con un subsistema, sino que reformula verbalmente el síntoma como un sacrificio positivo que mantiene la cohesión de todo el sistema, sin tomar partido activo por ningún miembro. Solapamiento parcial: ambas intervienen sobre el equilibrio sistémico, pero una lo hace mediante alianza activa y la otra mediante reencuadre verbal neutral.",
