    nota:
      "Ambos conceptos sostienen que la identidad y el deseo del sujeto no se originan de forma autónoma en su interior, sino que son moldeados desde fuera por estructuras que lo preceden y lo exceden. Pero la estructura que moldea es de naturaleza distinta: el deseo del Otro en Lacan remite al orden Simbólico transindividual (el lenguaje, la Ley, el deseo de los padres) que constituye al sujeto desde antes de su nacimiento, dentro de una relectura estructuralista del psicoanálisis; los discursos dominantes culturales en la terapia narrativa son historias y normas sociales históricamente situadas y contingentes (sobre el éxito, el género, la salud mental), modificables mediante la práctica política y conversacional, sin el aparato estructuralista fijo (Real-Simbólico-Imaginario) de Lacan. Análogo funcional: ambos sitúan el origen del deseo/identidad fuera del sujeto individual, pero uno en una estructura simbólica universal y el otro en discursos culturales históricamente contingentes y modificables.",
